package com.hms.ui;
import com.hms.dao.impl.*; import com.hms.model.User; import com.hms.service.*; import javax.swing.*; import java.awt.*;
public class MainFrame extends JFrame { public MainFrame(User user){setTitle("Hospital Management System - "+user.fullName()+" ("+user.role()+")");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1200,720);setLocationRelativeTo(null);PatientService ps=new PatientService(new PatientDaoImpl());DoctorService ds=new DoctorService(new DoctorDaoImpl());AppointmentService as=new AppointmentService(new AppointmentDaoImpl());BillingService bs=new BillingService(new BillingDaoImpl());JTabbedPane tabs=new JTabbedPane();tabs.addTab("Patients",new PatientPanel(ps));tabs.addTab("Doctors",new DoctorPanel(ds));tabs.addTab("Appointments",new AppointmentPanel(as,ps,ds));tabs.addTab("Billing / Visit Slips",new BillingPanel(bs,as));add(tabs,BorderLayout.CENTER);}}
